//! 🕸️ Writes graph nodes, exact positions, declared ports, typed properties and directed edges.
use super::{SemioGraphSnapshot,SemioGraphNode,SemioGraphPort,SemioGraphPortKind,SemioGraphEdge};
use crate::standards::v1::subsets::{base::schema::snapshot::native_encoding::{self,Writer},value::schema::snapshot::native_encoding as values};
use store::sqlite_snapshot::{SnapshotEncoding,SqliteSnapshotControl};
pub(super) fn encode(snapshot:&SemioGraphSnapshot,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,String>{native_encoding::encode(encoding,"semio s.stdio.semio.graph.dsl v1\n","s.stdio.semio.graph.pack v1",control,|writer,encoding|fields(snapshot,writer,encoding))}
fn port(port:&SemioGraphPort,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;writer.string(&port.name,encoding)?;writer.delimiter(b",",encoding)?;writer.byte(if encoding==SnapshotEncoding::Binary{match port.kind{SemioGraphPortKind::In=>0,SemioGraphPortKind::Out=>1,SemioGraphPortKind::InOut=>2}}else{super::enc_port_kind(port.kind) as u8})?;writer.delimiter(b"]",encoding)}
fn node(node:&SemioGraphNode,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;for field in [&node.id.value,&node.kind,&node.label]{writer.string(field,encoding)?;writer.delimiter(b",",encoding)?;}writer.hex_number(node.position.x,encoding)?;writer.delimiter(b",",encoding)?;writer.hex_number(node.position.y,encoding)?;writer.delimiter(b",",encoding)?;writer.list(&node.ports,encoding,|writer,item|port(item,writer,encoding))?;writer.delimiter(b",",encoding)?;writer.list(&node.properties,encoding,|writer,item|values::entry(item,writer,encoding,0))?;writer.delimiter(b"]",encoding)}
fn edge(edge:&SemioGraphEdge,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.delimiter(b"[",encoding)?;for(index,field)in [&edge.id.value,&edge.source.value,&edge.target.value,&edge.kind,&edge.label].into_iter().enumerate(){if index!=0{writer.delimiter(b",",encoding)?;}writer.string(field,encoding)?;}writer.delimiter(b"]",encoding)}
pub(crate) fn fields(snapshot:&SemioGraphSnapshot,writer:&mut Writer<'_,'_,'_>,encoding:SnapshotEncoding)->Result<(),String>{writer.entities(1)?;if encoding==SnapshotEncoding::Binary{writer.byte(1)?}else{writer.bytes(b"schema=")?}writer.string(&snapshot.schema,encoding)?;writer.delimiter(b"\nnodes=",encoding)?;writer.list(&snapshot.nodes,encoding,|writer,item|node(item,writer,encoding))?;writer.delimiter(b"\nedges=",encoding)?;writer.list(&snapshot.edges,encoding,|writer,item|edge(item,writer,encoding))}
